function money(value) {
  return Number(value || 0).toLocaleString("en-PH", {
    style: "currency",
    currency: "PHP",
  });
}

function formatDateTime(value) {
  return value ? formatDateTime12h(value) : "—";
}

// Anything the vet dispenses/administers with a meaningful purchase
// quantity is treated as "Medicine" so it gets prescription tracking and an
// adjustable quantity at POS -- only lab tests (one-time services, no
// partial-purchase concept) and unrecognized categories stay out of it.
function guessItemType(inventoryItem) {
  const haystack = `${inventoryItem.category || ""} ${inventoryItem.item_name || ""}`.toLowerCase();
  if (haystack.includes("test") || haystack.includes("lab") || haystack.includes("diagnostic")) return "Test";
  if (
    haystack.includes("medic") || haystack.includes("drug") || haystack.includes("vaccine") ||
    haystack.includes("antibiotic") || haystack.includes("supplement") || haystack.includes("parasite") ||
    haystack.includes("inflammat") || haystack.includes("eye drop") || haystack.includes("ear drop") ||
    haystack.includes("injection") || haystack.includes("ointment") || haystack.includes("tablet") ||
    haystack.includes("capsule") || haystack.includes("syrup")
  ) return "Medicine";
  return "Product";
}

function statusClass(status) {
  return String(status || "Unpaid").toLowerCase().replace(/\s+/g, "-");
}

function StatusPill({ status }) {
  return <span className={`payment-status status-${statusClass(status)}`}>{status || "Unpaid"}</span>;
}

// Every pet a transaction paid for -- a multi-pet visit shares one queue
// ticket, so its one payment covers all of them.
function transactionPetNames(transaction) {
  const pets = transaction?.pets?.length ? transaction.pets : [transaction?.pet].filter(Boolean);
  return pets.map((pet) => pet.pet_name).filter(Boolean);
}

function remainingBalance(transaction) {
  return Math.max(0, Number(transaction?.total_amount || 0) - Number(transaction?.amount_paid || 0));
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function receiptRows(transaction) {
  const serviceRows = Number(transaction.checkup_fee || 0) > 0
    ? [{ id: "checkup", item_name: "Checkup / consultation service", quantity: 1, unit_price: transaction.checkup_fee, line_total: transaction.checkup_fee }]
    : [];
  return [...serviceRows, ...(transaction.transaction_items || [])];
}

// Pure HTML builder -- no window.open/print here. The caller shows this
// inside the shared PrintPreviewModal so the user reviews the invoice
// before printing, instead of a print dialog firing immediately.
function buildReceiptHtml(transaction) {
  const rows = receiptRows(transaction).map((item) => `
    <tr><td>${escapeHtml(item.item_name)} × ${escapeHtml(item.quantity)}</td><td>${escapeHtml(money(item.line_total))}</td></tr>
  `).join("");
  // Discount is only ever shown for older transactions that already carry a
  // stored discount_amount from before this feature was removed -- new
  // transactions always have 0, so the line never appears for them.
  const hasDiscount = Number(transaction.discount_amount) > 0;
  const discountRow = hasDiscount ? `<div class="row"><span>Discount</span><span>-${escapeHtml(money(transaction.discount_amount))}</span></div>` : "";
  const balance = remainingBalance(transaction);
  const balanceRow = balance > 0 ? `<div class="row balance"><span>Remaining Balance</span><span>${escapeHtml(money(balance))}</span></div>` : "";
  const splitRows = transaction.payment_method === "Split Payment" && transaction.split_payment_details
    ? Object.entries(transaction.split_payment_details)
      .filter(([, value]) => Number(value) > 0)
      .map(([method, value]) => `<div class="row split"><span>${escapeHtml(method)} portion</span><span>${escapeHtml(money(value))}</span></div>`)
      .join("")
    : "";
  return `<!doctype html><html><head><title>Invoice ${escapeHtml(transaction.or_number)}</title><style>@page{size:A4;margin:16mm}body{font-family:Arial,sans-serif;color:#1e313a;margin:28px}.center{text-align:center}.muted{color:#617681;font-size:12px}table{width:100%;border-collapse:collapse;margin:18px 0}td{padding:8px 0;border-bottom:1px dashed #bfd0d7}td:last-child{text-align:right;white-space:nowrap}.total{font-size:18px;font-weight:700}.row{display:flex;justify-content:space-between;padding:5px 0}.row.balance{font-weight:700;color:#b0620a}.row.split{padding-left:14px;color:#536b78;font-size:13.5px}</style></head><body><div class="center"><h2>PawCruz Veterinary Clinic</h2><p class="muted">Official POS Invoice</p><strong>${escapeHtml(transaction.or_number || transaction.id)}</strong><p class="muted">${escapeHtml(formatDateTime(transaction.created_at))}</p></div><div class="row"><span>Pet owner</span><b>${escapeHtml(transaction.owner?.full_name || "—")}</b></div><div class="row"><span>${transactionPetNames(transaction).length > 1 ? "Pets" : "Pet"}</span><b>${escapeHtml(transactionPetNames(transaction).join(", ") || "—")}</b></div>${transactionPetNames(transaction).length > 1 && transaction.queue_number ? `<div class="row"><span>Shared queue ticket</span><b>${escapeHtml(transaction.queue_number)}</b></div>` : ""}<div class="row"><span>Cashier</span><b>${escapeHtml(transaction.cashier?.full_name || "—")}</b></div><table>${rows}</table>${discountRow}<div class="row total"><span>Total</span><span>${escapeHtml(money(transaction.total_amount))}</span></div><div class="row"><span>Amount paid</span><span>${escapeHtml(money(transaction.amount_paid))}</span></div><div class="row"><span>Change</span><span>${escapeHtml(money(transaction.change_amount))}</span></div>${balanceRow}<div class="row"><span>Method</span><span>${escapeHtml(transaction.payment_method)}</span></div>${splitRows}<p class="center muted">Status: ${escapeHtml(transaction.payment_status)}</p></body></html>`;
}

